namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public int TotalStars { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount == 0 ? 0 : (double)TotalStars / RatingCount;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Tomato sauce, Fresh mozzarella, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread tomato sauce evenly.\n4. Add torn mozzarella pieces.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.", TotalStars = 18, RatingCount = 4 },
        new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Pancetta, Eggs, Parmesan cheese, Black pepper, Salt", Steps = "1. Cook spaghetti in salted boiling water.\n2. Fry pancetta until crispy.\n3. Whisk eggs with grated Parmesan and pepper.\n4. Toss hot pasta with pancetta.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra Parmesan.", TotalStars = 22, RatingCount = 5 },
        new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast, Yogurt, Tikka spice mix, Tomato puree, Heavy cream, Onion, Garlic, Ginger, Rice", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or bake chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato puree and simmer.\n5. Stir in cream and cooked chicken.\n6. Serve over basmati rice.", TotalStars = 15, RatingCount = 3 },
        new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce, Sugar, Eggs, Green onions", Steps = "1. Soak rice noodles in warm water.\n2. Press and cube tofu, then pan-fry until golden.\n3. Make sauce: mix tamarind, fish sauce, and sugar.\n4. Scramble eggs in wok.\n5. Add noodles and sauce, toss together.\n6. Top with peanuts, bean sprouts, and lime.", TotalStars = 12, RatingCount = 3 },
        new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheese, Sour cream, Taco seasoning, Onion", Steps = "1. Brown ground beef with diced onion.\n2. Add taco seasoning and water, simmer.\n3. Warm taco shells in oven.\n4. Dice tomato and shred lettuce.\n5. Fill shells with beef.\n6. Top with lettuce, tomato, cheese, and sour cream.", TotalStars = 20, RatingCount = 5 },
        new() { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Red onion, Cilantro, Jalapeño, Tomato, Salt, Garlic", Steps = "1. Halve and pit avocados.\n2. Mash avocado to desired consistency.\n3. Finely dice onion, tomato, jalapeño, and cilantro.\n4. Mix all ingredients together.\n5. Add lime juice and salt to taste.\n6. Serve with tortilla chips.", TotalStars = 9, RatingCount = 2 },
        new() { Id = 7, Title = "Green Curry", Category = "Thai", Ingredients = "Green curry paste, Coconut milk, Chicken thighs, Thai basil, Bamboo shoots, Bell pepper, Fish sauce, Sugar, Rice", Steps = "1. Heat curry paste in a wok.\n2. Add half the coconut milk, stir until oil separates.\n3. Add sliced chicken, cook through.\n4. Pour in remaining coconut milk.\n5. Add vegetables, fish sauce, and sugar.\n6. Finish with Thai basil, serve with rice.", TotalStars = 14, RatingCount = 3 },
        new() { Id = 8, Title = "Dal Tadka", Category = "Indian", Ingredients = "Yellow lentils, Tomato, Onion, Garlic, Cumin seeds, Mustard seeds, Turmeric, Red chili, Ghee, Cilantro", Steps = "1. Wash and boil lentils with turmeric until soft.\n2. Mash lentils lightly.\n3. Heat ghee, add cumin and mustard seeds.\n4. Add chopped onion, garlic, and tomato.\n5. Pour tempering over lentils and stir.\n6. Garnish with cilantro and serve with rice or naan.", TotalStars = 10, RatingCount = 2 },
    };

    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalStars += stars;
            recipe.RatingCount++;
        }
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

