@page "/recipes/{CategoryName}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-4 mt-2">
            @foreach (var recipe in recipes)
            {
                <div class="col">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                @if (recipe.RatingCount > 0)
                                {
                                    <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                                }
                                else
                                {
                                    <span>No ratings yet</span>
                                }
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public string CategoryName { get; set; } = "";

    private IReadOnlyList<RecipeShare.Services.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<div class="container">
    @if (recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <nav aria-label="breadcrumb">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/">Home</a></li>
                <li class="breadcrumb-item"><a href="/recipes/@recipe.Category.ToLower()">@recipe.Category</a></li>
                <li class="breadcrumb-item active">@recipe.Title</li>
            </ol>
        </nav>

        <h1>@recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@recipe.Category</span>

        <div class="row mt-3">
            <div class="col-md-4">
                <div class="card">
                    <div class="card-header"><strong>Ingredients</strong></div>
                    <ul class="list-group list-group-flush">
                        @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                        {
                            <li class="list-group-item">@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card">
                    <div class="card-header"><strong>Instructions</strong></div>
                    <div class="card-body">
                        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>

        <div class="card mt-4">
            <div class="card-body">
                <h5>Rate this Recipe</h5>
                <p class="text-muted mb-2">
                    @if (recipe.RatingCount > 0)
                    {
                        <span>Average: ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                    }
                    else
                    {
                        <span>No ratings yet — be the first!</span>
                    }
                </p>
                <StarRating RecipeId="@recipe.Id" />
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeShare.Services.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

@if (submitted)
{
    <div class="alert alert-success py-2">Thanks for rating! You gave @submittedStars star(s).</div>
}
else
{
    <div class="d-flex align-items-center gap-1">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-lg p-0 border-0 @(star <= hoverRating ? "text-warning" : "text-secondary")"
                    @onmouseover="() => hoverRating = star"
                    @onmouseout="() => hoverRating = 0"
                    @onclick="() => SubmitRating(star)"
                    aria-label="Rate @star stars">
                ★
            </button>
        }
        @if (hoverRating > 0)
        {
            <span class="ms-2 text-muted">@hoverRating star(s)</span>
        }
    </div>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int hoverRating;
    private bool submitted;
    private int submittedStars;

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        submittedStars = stars;
        submitted = true;
    }
}

